begin;
-- =========================================================
-- B · 상품·채소 초기 데이터 (seed)
-- 원본: src/data/mock/vegetables.ts, products.ts (변환기로 자동 생성)
-- 202610110002_product_display_fields.sql 적용 후 실행합니다 (tagline·rating·review_count).
-- 별점·리뷰 수는 시연용 가상 데이터입니다.
-- 상품 이름의 유기농·무농약·산지 표시는 시연용 가상 정보입니다 (실제 인증 아님).
-- 채소 21개, 상품 71개 (판매 중 67개 + 판매 종료 4개: 휜 무·휜 가지·휜 새송이 2개)
-- 농가 이름·가격·보관법 문구는 시연용 가상 데이터입니다.
-- 여러 번 실행해도 중복되지 않도록 id 기준으로 덮어써요(upsert).
-- 순서: 채소 먼저 → 상품 (상품이 채소를 가리키기 때문)
-- =========================================================

on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  description = excluded.description,
  storage_guide = excluded.storage_guide,
  prep_guide = excluded.prep_guide,
  season = excluded.season,
  image_path = excluded.image_path;

on conflict (id) do update set
  vegetable_id = excluded.vegetable_id,
  name = excluded.name,
  description = excluded.description,
  price = excluded.price,
  original_price = excluded.original_price,
  unit = excluded.unit,
  ugly_reason = excluded.ugly_reason,
  condition_note = excluded.condition_note,
  farm_name = excluded.farm_name,
  farm_region = excluded.farm_region,
  farm_story = excluded.farm_story,
  image_path = excluded.image_path,
  is_seasonal = excluded.is_seasonal,
  is_featured = excluded.is_featured,
  is_active = excluded.is_active,
  tagline = excluded.tagline,
  rating = excluded.rating,
  review_count = excluded.review_count;

commit;
